/**
 * Fetches a file generated by the docs build (`apps/docs/public/markdown/<file>`) from the docs
 * deployment, so www doesn't depend on the docs build output. Null when unavailable.
 */
export async function fetchDocsMarkdown(file: string): Promise<string | null> {
  const docsUrl = process.env.NEXT_PUBLIC_DOCS_URL
  if (!docsUrl) return null

  const response = await fetch(`${docsUrl}/markdown/${file}`)
  return response.ok ? response.text() : null
}
